PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS dishes (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price REAL NOT NULL CHECK(price >= 0));
CREATE TABLE IF NOT EXISTS restaurant_tables (id INTEGER PRIMARY KEY, number INTEGER NOT NULL UNIQUE, capacity INTEGER NOT NULL CHECK(capacity > 0));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, client_id INTEGER NOT NULL REFERENCES clients(id), table_id INTEGER NOT NULL REFERENCES restaurant_tables(id), status TEXT NOT NULL DEFAULT 'Новый', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, dish_id INTEGER NOT NULL REFERENCES dishes(id), quantity INTEGER NOT NULL CHECK(quantity > 0));
